def load() -> pd.DataFrame:
    with open('data/legal/input/csn-data-book-2024-csv/CSVs/2024_CSN_Report_Count.csv', 'r') as f:
        lines = f.readlines()[:20]
    return pd.DataFrame({'raw_lines': lines})

def process(calculate_relative_increase) -> pd.DataFrame:
    max_row = calculate_relative_increase.loc[calculate_relative_increase['Relative_Increase'].idxmax()]
    return pd.DataFrame([{'Year': int(max_row['Year']), 'Max_Relative_Increase': max_row['Relative_Increase']}])
